package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues2D_removeColumn_TriageGen2Test {

    private DefaultKeyedValues2D dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }

    @Test
    public void testRemoveColumn_NonExistentKey() {
        dataset.addValue(10.0, "Row1", "Col1");
        dataset.addValue(20.0, "Row2", "Col1");

        // Remove a key that doesn't exist in columnKeys or in any row
        dataset.removeColumn("NonExistent");

        assertEquals(2, dataset.getRowCount());
        assertEquals(1, dataset.getColumnCount());
        assertEquals("Col1", dataset.getColumnKeys().get(0));
    }

    @Test
    public void testRemoveColumn_ExistingKey() {
        dataset.addValue(10.0, "Row1", "Col1");
        dataset.addValue(20.0, "Row1", "Col2");
        dataset.addValue(30.0, "Row2", "Col1");
        dataset.addValue(40.0, "Row2", "Col2");

        dataset.removeColumn("Col1");

        // Check column count decreased
        assertEquals(1, dataset.getColumnCount());
        assertEquals("Col2", dataset.getColumnKeys().get(0));

        // Check values in rows are removed
        assertNull(dataset.getValue("Row1", "Col1"));
        assertNull(dataset.getValue("Row2", "Col1"));

        // Check remaining values are intact
        assertEquals(20.0, dataset.getValue("Row1", "Col2").doubleValue(), 0.0001);
        assertEquals(40.0, dataset.getValue("Row2", "Col2").doubleValue(), 0.0001);
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Test removing from an empty dataset
        dataset.removeColumn("AnyKey");
        assertEquals(0, dataset.getRowCount());
        assertEquals(0, dataset.getColumnCount());
    }

    @Test
    public void testRemoveColumn_SingleValue() {
        dataset.addValue(100.0, "Row1", "Col1");

        dataset.removeColumn("Col1");

        assertEquals(0, dataset.getColumnCount());
        assertEquals(1, dataset.getRowCount()); // Row still exists but is empty
        assertNull(dataset.getValue("Row1", "Col1"));
    }

    @Test
    public void testRemoveColumn_MultipleColumns() {
        dataset.addValue(1.0, "R1", "C1");
        dataset.addValue(2.0, "R1", "C2");
        dataset.addValue(3.0, "R1", "C3");

        dataset.removeColumn("C2");

        assertEquals(2, dataset.getColumnCount());
        List<Comparable> keys = dataset.getColumnKeys();
        assertTrue(keys.contains("C1"));
        assertTrue(keys.contains("C3"));
        assertTrue(!keys.contains("C2"));
    }

    @Test
    public void testRemoveColumn_NullKey() {
        // Testing behavior with null (if the underlying implementation allows it)
        dataset.addValue(10.0, "Row1", null);
        dataset.addValue(20.0, "Row2", "Col1");

        dataset.removeColumn(null);

        assertEquals(1, dataset.getColumnCount());
        assertEquals("Col1", dataset.getColumnKeys().get(0));
        assertNull(dataset.getValue("Row1", null));
    }
}
